fn solve(input: Vec<char>) -> Vec<char> {
    // Extract the four digit characters
    let digits = &input[..4];
    // Convert them to integer values 0..9
    let nums: Vec<i32> = digits
        .iter()
        .map(|&c| c.to_digit(10).unwrap() as i32)
        .collect();

    // Try all 2^3 = 8 ways of choosing '+' or '-' for the three slots
    for mask in 0..8 {
        let mut total = nums[0];
        // ops[i] will be the operator between nums[i] and nums[i+1]
        let mut ops = ['+'; 3];
        
        for i in 0..3 {
            if (mask >> i) & 1 == 1 {
                total += nums[i + 1];
                ops[i] = '+';
            } else {
                total -= nums[i + 1];
                ops[i] = '-';
            }
        }

        // Check if this combination yields 7
        if total == 7 {
            // Build the output Vec<char> of length 10:
            // d1, op1, d2, op2, d3, op3, d4, '=', '7', '\n'
            let mut result = Vec::with_capacity(10);
            result.push(digits[0]);
            result.push(ops[0]);
            result.push(digits[1]);
            result.push(ops[1]);
            result.push(digits[2]);
            result.push(ops[2]);
            result.push(digits[3]);
            result.push('=');
            result.push('7');
            result.push('\n');
            return result;
        }
    }

    // According to the problem statement, there is always a solution.
    // This line is just to satisfy the type checker.
    Vec::new()
}